/** Resultado de 60010000-OBTEN-FECHA-BD02. */
record FechasControl(int csi, LocalDate fechaLinea, LocalDate fechaLote,
                     LocalDate ultimoArchivoAplicado) {}

@Component
@RequiredArgsConstructor
class FechasControlService {
    private final ControlS500Repository b02;      // S500B02CONTROL, primer registro
    private final CalendarioBancario calendario;  // S000LIBFEC, semana 65, festivos 1
    private final P191Properties props;

    FechasControl lee() {
        var c = b02.primero().orElseThrow(() -> new ProcesoAbortadoException("ERROR REG. DE CONTROL VACIO"));
        LocalDate lote = calendario.habilAnterior(c.fechaLinea());          // 60060000-OBTEN-ANT-FEC-HABIL
        LocalDate ultimo = c.ultArchAplicado(14);                            // B02-ULT-ARCH-APLI(14)
        if (!ultimo.isAfter(props.fechaArranqueControl())) {
            ultimo = lote;                                                   // también se escribe en el registro en memoria
        }
        return new FechasControl(c.numCsi(), c.fechaLinea(), lote, ultimo);
    }
}

@Component
@RequiredArgsConstructor
class VersionGuard implements JobExecutionListener {
    private final ControlVersiones versiones;          // CTLVERS / maestro S100
    @Value("${p191.version:25MTP004}") private String miVersion;

    @Override
    public void beforeJob(JobExecution job) {
        if (versiones.compara("S500P191", miVersion) < 0) {
            throw new ProcesoAbortadoException("VER. EJECUTADA DIF. A VERSIONES");  // CALL SYSTEM DMTERMINATE
        }
    }
}

enum TipoProceso { NEUTRALIZADO, NORMAL, REPROCESO }   // WKS-TIPO-PROCESO 0, 8, 9

record VentanaPunteo(TipoProceso tipo, LocalDate inicio, LocalDate fin) {

    /** 30010000-DECIDE-TIPO-PROCESO. fechaParametro viene de TASKVALUE (W77-VAL-191). */
    static VentanaPunteo decide(Optional<LocalDate> fechaParametro, FechasControl c) {
        if (fechaParametro.isEmpty()) {
            return new VentanaPunteo(TipoProceso.NORMAL, c.ultimoArchivoAplicado(), c.fechaLote());
        }
        LocalDate f = fechaParametro.get();
        TipoProceso tipo = f.isAfter(c.ultimoArchivoAplicado())
                ? TipoProceso.REPROCESO           // W77-REPROCESO-VAL = 1
                : TipoProceso.NEUTRALIZADO;       // tipo 0: procesa la fecha pero no mueve B02
        return new VentanaPunteo(tipo, f, f);
    }

    boolean actualizaControl() { return tipo != TipoProceso.NEUTRALIZADO; }
}

@Bean
Job punteoS054(JobRepository repo, VersionGuard version, Step ventana, Flow punteoDeUnDia,
               JobExecutionDecider quedanFechas) {
    return new JobBuilder("S500P191", repo)
            .listener(version)
            .start(ventana)                                  // VentanaPunteo en el ExecutionContext
            .next(quedanFechas).on("FIN").end()
            .from(quedanFechas).on("PROCESA").to(punteoDeUnDia)
            .next(quedanFechas)                              // PERFORM ... UNTIL INI > FIN
            .end()
            .build();
}

/** 20011100-PROCESA-X-DIA-CON como flujo de steps sobre la fecha actual. */
@Bean
Flow punteoDeUnDia(Step esperaArchivosS054, Step concentraS500, Step cargaS054,
                   Step conciliacion, Step revisaCifras, Step totales, Step avanzaControl) {
    return new FlowBuilder<SimpleFlow>("punteoDeUnDia")
            .start(esperaArchivosS054)       // 20014000-VALIDA-ARC-S054
            .next(concentraS500)             // 20013000-PROCESA-ARC-S500
            .next(cargaS054)                 // 20014100-PROCESA-ARC-S054
            .next(conciliacion)              // 20015000-GENERA-REPORTES
            .next(revisaCifras)              // 20015200-REVISA-CIFRAS
            .next(totales)                   // 20016000-GENERA-TOTALES
            .next(avanzaControl)             // condicional: VentanaPunteo.actualizaControl()
            .build();
}

/** I02-REG-S500-CRCHQRA-TEMPORAL: 65 bytes, campos binarios COMP. */
public record MovimientoS500(
        int tipoRegistro,
        long autorizacionS500,      // 9(12) COMP
        String contrato,            // 9(12) COMP, se conserva como texto con ceros
        int producto, int instrumento, int moneda,
        int claveTransaccion,       // 3047 = abono
        BigDecimal importe,         // 9(10)V99 COMP -> escala 2
        long referencia,
        long autorizacionS054,
        LocalDate fechaMaquina, LocalTime horaMaquina,
        int movimiento, int origen, int banco,
        Pan numeroTarjeta,          // 9(16) COMP: tipo dedicado, nunca se registra en claro
        int sucursalPromotora, int sucursalOperadora, int cajaOperadora) {}

/** Valor de tarjeta enmascarado en toString y logs. */
public record Pan(String valor) {
    @Override public String toString() { return "************" + valor.substring(12); }
}

@Component
@StepScope
@RequiredArgsConstructor
class EsperaArchivoS054Tasklet implements Tasklet {

    private final ArchivosS054 archivos;            // un archivo por día natural (incluye inhábiles previos)
    private final VentanaHoraria ventana;
    private final P191Properties props;             // p191.s054.reintento: PT20S

    @Override
    public RepeatStatus execute(StepContribution c, ChunkContext ctx) throws InterruptedException {
        for (Path p : archivos.requeridos()) {      // 60070000-OBTEN-NUM-ARC-S054
            while (!Files.exists(p)) {               // ATTRIBUTE RESIDENT = 0
                ventana.verificaCorte(p, archivos.fechaLinea());   // 60074000-VERIFICA-CAMBIO
                Thread.sleep(props.s054().reintento().toMillis());   // WAIT (20)
            }
            archivos.validaHeader(p);               // 50032000-ABRE-Y-VAL-ARC-S054
        }
        return RepeatStatus.FINISHED;
    }
}

@Component
@RequiredArgsConstructor
class VentanaHoraria {
    private final Clock reloj;
    private final P191Properties props;        // p191.s054.hora-limite: 09:00:00, aviso-cada: 90 (30 min con reintento de 20 s)
    private int ciclos;                          // WKS-CON-TIME

    /** 60074000-VERIFICA-CAMBIO + 60075000-LEYENDA. */
    void verificaCorte(Path faltante, LocalDate fechaLinea) {
        ciclos++;
        boolean mismoDia = LocalDate.now(reloj).equals(fechaLinea);   // B02-FECHA-LINEA = fecha de máquina
        if (mismoDia && LocalTime.now(reloj).isAfter(props.s054().horaLimite())) {
            log.warn("ARCHIVO {} NO EXISTE, ESTOY FUERA DE HORARIO TERMINO SIN PUNTEO", faltante);
            throw new JobInterruptedException("SIN PUNTEO");   // hoy: 90000000-FIN, STOP RUN normal
        }
        if (ciclos % props.s054().avisoCada() == 0) {
            log.warn("ARCHIVO {} NO EXISTE, HORARIO LIMITE {} FAVOR DE PONERLO RESIDENTE",
                     faltante, props.s054().horaLimite());
        }
    }
}

/** Resultado de comparar la cabeza de cada archivo. */
sealed interface Punteo permits Punteo.Aplicado, Punteo.SoloS500, Punteo.SoloS054 {
    record Aplicado(MovimientoS500 s500, MovimientoS054 s054) implements Punteo {}
    record SoloS500(MovimientoS500 s500) implements Punteo {}
    record SoloS054(MovimientoS054 s054) implements Punteo {}
}

/** 20015100-EFECTUA-MATCH sobre dos PeekableItemReader ordenados por (tarjeta, importe). */
@Component
@StepScope
@RequiredArgsConstructor
class ConciliacionReader implements ItemReader<Punteo> {
    private final SingleItemPeekableItemReader<MovimientoS500> s500;
    private final SingleItemPeekableItemReader<MovimientoS054> s054;

    private static final Comparator<Llave> ORDEN =
            Comparator.comparing(Llave::tarjeta).thenComparing(Llave::importe);

    @Override
    public Punteo read() throws Exception {
        var a = s500.peek();
        var b = s054.peek();
        if (a == null && b == null) return null;                 // ambos EOF
        if (a == null) return new Punteo.SoloS054(s054.read());
        if (b == null) return new Punteo.SoloS500(s500.read());
        int cmp = ORDEN.compare(a.llave(), b.llave());
        if (cmp == 0) return new Punteo.Aplicado(s500.read(), s054.read());
        return cmp > 0 ? new Punteo.SoloS054(s054.read())        // el menor avanza
                       : new Punteo.SoloS500(s500.read());
    }
}

@Component
@StepScope
class TotalesPunteo {
    // WKS-TOT-REGISTROS: se reinician en cada fecha (20011100)
    private long numAplicados, numDiferencias, numCargos, numAbonos;
    private BigDecimal impAplicados = cero(), impDiferencias = cero(),
                       impCargos = cero(), impAbonos = cero();

    /** 20015120-IMPRIME-REP-DIFE-S500: todo faltante en S054 suma a abonos. */
    RenglonDiferencia soloS500(MovimientoS500 m, P191Properties props) {
        numDiferencias++; numAbonos++;
        impDiferencias = impDiferencias.add(m.importe());
        impAbonos = impAbonos.add(m.importe());

        boolean esAbono = m.claveTransaccion() == props.claveAbono();   // p191.clave-abono: 3047
        return new RenglonDiferencia(m,
                esAbono ? "ABONO" : String.valueOf(m.claveTransaccion()),
                esAbono ? "CARGO A CUENTA" : " VERIFIQUE    ");
    }

    private static BigDecimal cero() { return BigDecimal.ZERO.setScale(2); }
}

@Service
@RequiredArgsConstructor
class ControlS500Service {

    private final ControlS500Repository b02;

    /** 30051000-ACTUALIZA-BD02CONTROL. */
    @Transactional
    public void registraAplicacion(LocalDate siguienteHabil) {
        ControlS500 c = b02.findPrimeroForUpdate()                     // SET TO BEGINNING + LOCK
                .orElseThrow(() -> new ProcesoAbortadoException("ERROR B02CONTROL VACIO"));
        c.setUltArchAplicado(14, siguienteHabil);                       // B02-ULT-ARCH-APLI(14)
        // BEGIN-TRANSACTION / STORE / END-TRANSACTION: el commit lo da @Transactional
    }
}

interface ControlS500Repository extends JpaRepository<ControlS500, Long> {
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("select c from ControlS500 c order by c.id limit 1")
    Optional<ControlS500> findPrimeroForUpdate();
}
